#!/usr/bin/env python3
"""Remove ShadowPot's generated files.

    python3 tools/clean.py          # generated logs, sample database, report
    python3 tools/clean.py --all    # also every database, including real ones

This exists instead of `rm -rf` lines in the Makefile for one reason: it
refuses to delete anything outside this repository. A Makefile recipe like

    rm -rf $(DATA_DIR)

deletes the whole filesystem if DATA_DIR is ever empty or unset, and nothing
about the recipe makes that visible when you read it. Every path here is
resolved and checked against the repository root before anything is removed,
symlinks are never followed out of the tree, and what was deleted is printed.

What is deliberately NOT removed by the default run:

  reports/sample-report.md   committed, so a stranger can see the output
                             without running anything
  data/real.db               a real deployment's database. The logs behind it
                             are not reproducible -- you cannot regenerate a
                             week of real attacks -- so it takes --all, and
                             the Makefile additionally demands CONFIRM=yes.
"""

from __future__ import annotations

import argparse
import pathlib
import shutil
import sys

REPO_ROOT = pathlib.Path(__file__).resolve().parent.parent

# Generated by the pipeline and always reproducible from a seed.
REGENERATABLE = (
    "data/sample-logs",
    "data/bench",
    "data/shadowpot.db",
    "reports/report.md",
    "reports/charts",
    ".check",
)

# Only with --all. Includes databases built from real captures.
EVERYTHING_ELSE = ("data",)

KEEP = ("reports/sample-report.md", "reports/.gitkeep")


def inside_repo(path: pathlib.Path) -> bool:
    """True only if `path` really lives under the repository root.

    resolve() collapses symlinks, so a symlinked data/ pointing at $HOME
    cannot be used to walk out of the tree.
    """
    try:
        resolved = path.resolve()
    except OSError:
        return False
    if resolved == REPO_ROOT:
        return False          # never the repository itself
    return REPO_ROOT in resolved.parents


def remove(relative: str) -> str | None:
    path = REPO_ROOT / relative
    if not path.exists() and not path.is_symlink():
        return None
    if not inside_repo(path):
        print(f"REFUSING to remove {path}: it resolves outside {REPO_ROOT}",
              file=sys.stderr)
        return None
    if path.is_dir() and not path.is_symlink():
        shutil.rmtree(path)
        return f"{relative}/"
    path.unlink()
    return relative


def prune_pycache() -> int:
    removed = 0
    for cache in REPO_ROOT.rglob("__pycache__"):
        if cache.is_dir() and inside_repo(cache):
            shutil.rmtree(cache, ignore_errors=True)
            removed += 1
    return removed


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--all", action="store_true",
                        help="also remove every database, including any built "
                             "from real honeypot logs")
    args = parser.parse_args(argv)

    targets = list(REGENERATABLE)
    if args.all:
        targets += list(EVERYTHING_ELSE)

    removed = [name for name in (remove(t) for t in targets) if name]
    caches = prune_pycache()

    if removed:
        print("removed:")
        for name in removed:
            print(f"  {name}")
    else:
        print("nothing to remove")
    if caches:
        print(f"removed {caches} __pycache__ director"
              f"{'y' if caches == 1 else 'ies'}")

    for name in KEEP:
        if (REPO_ROOT / name).exists():
            print(f"kept:     {name}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
